from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal


class ExpiredPromotionError(Exception):
    def __init__(self, code: str, expired_at: datetime):
        super().__init__(f"Promotion {code} expired at {expired_at.isoformat()}")
        self.code = code
        self.expired_at = expired_at


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


def checkout_total(subtotal: Decimal, promotion: Promotion | None, now: datetime) -> Decimal:
    """Provisional policy: an expired promotion rejects the order."""
    if promotion is None:
        return subtotal
    if now >= promotion.expires_at:
        raise ExpiredPromotionError(promotion.code, promotion.expires_at)
    return (subtotal * (Decimal(100) - promotion.percent_off) / 100).quantize(Decimal("0.01"))
EOF
cat > test_checkout.py <<'EOF'
from datetime import datetime, timedelta
from decimal import Decimal

import pytest

from checkout import ExpiredPromotionError, Promotion, checkout_total

NOW = datetime(2026, 11, 14, 12, 0)
SUB = Decimal("100.00")


def promo(delta):
    return Promotion("SAVE10", Decimal(10), NOW + delta)


def test_no_promotion():
    assert checkout_total(SUB, None, NOW) == SUB


def test_valid_promotion_applies():
    assert checkout_total(SUB, promo(timedelta(days=1)), NOW) == Decimal("90.00")


def test_expired_promotion_rejects_order():
    with pytest.raises(ExpiredPromotionError) as e:
        checkout_total(SUB, promo(-timedelta(seconds=1)), NOW)
    assert e.value.code == "SAVE10"


def test_promotion_expiring_exactly_now_is_expired():
    with pytest.raises(ExpiredPromotionError):
        checkout_total(SUB, promo(timedelta(0)), NOW)
EOF
python -m pytest -q 2>&1 | tail -3

